const require_index = require("../useLatest/index.js");
let react = require("react");
//#region src/useRafFn/index.ts
const useRafFn = (callback, initiallyActive = true) => {
	const raf = (0, react.useRef)(null);
	const rafActivity = (0, react.useRef)(false);
	const rafCallback = require_index.useLatest(callback);
	const step = (0, react.useCallback)((time) => {
		if (rafActivity.current) {
			rafCallback.current(time);
			raf.current = requestAnimationFrame(step);
		}
	}, [rafCallback]);
	const result = (0, react.useMemo)(() => [
		() => {
			if (rafActivity.current) {
				rafActivity.current = false;
				raf.current && cancelAnimationFrame(raf.current);
			}
		},
		() => {
			if (!rafActivity.current) {
				rafActivity.current = true;
				raf.current = requestAnimationFrame(step);
			}
		},
		() => rafActivity.current
	], [step]);
	(0, react.useEffect)(() => {
		if (initiallyActive) result[1]();
		return result[0];
	}, [initiallyActive, result]);
	return result;
};
//#endregion
exports.useRafFn = useRafFn;
